$ui.BtnDeleteCurrent.Add_Click({
    if (-not $script:lastOut) { return }
    $delPath = $script:lastOut
    $ans = [System.Windows.MessageBox]::Show(
        "Bạn có chắc chắn muốn xóa bản video này không?

File: $(Split-Path $delPath -Leaf)",
        "Xác nhận xóa video",
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Warning
    )
    if ($ans -eq [System.Windows.MessageBoxResult]::Yes) {
        $isReviewActive = ($ui.PanelRev -and $ui.PanelRev.Visibility -eq 'Visible' -and
            $script:queue -and $script:queue.Count -gt 0 -and $script:idx -ge 0 -and $script:idx -lt $script:queue.Count)
        $savedSource = $ui.Player.Source
        $savedPosition = [TimeSpan]::Zero
        try { $savedPosition = $ui.Player.Position } catch { }
        # Match the established play-button state used by track switching and seeking.
        $savedWasPlaying = ($ui.BtnPlay -and $ui.BtnPlay.Content -match 'Tạm dừng')
        $savedLastOut = $script:lastOut
        $savedActiveTrack = $script:activeTrack
        $savedPreviewingClean = $script:previewingClean
        $savedPreviewBadge = if ($ui.BadgePreviewMode) { $ui.BadgePreviewMode.Visibility } else { $null }
        $savedReviewVisibility = if ($ui.PanelRev) { $ui.PanelRev.Visibility } else { $null }
        $savedPanelPlayVisibility = if ($ui.PanelPlay) { $ui.PanelPlay.Visibility } else { $null }
        $savedNoVidVisibility = if ($ui.TxtNoVid) { $ui.TxtNoVid.Visibility } else { $null }

        $delResult = $null
        try { $delResult = Remove-ReelFiles $delPath }
        catch {
            $delResult = @{ Success = $false; Errors = @($_.Exception.Message); CleanupStatus = 'RecoveryRequired'; RecoveryPaths = @() }
        }
        if (-not $delResult -or -not $delResult.Success) {
            # Restore review state and the exact media source that was active before deletion.
            $script:lastOut = $savedLastOut
            $script:activeTrack = $savedActiveTrack
            $script:previewingClean = $savedPreviewingClean
            if ($ui.PanelRev -and $null -ne $savedReviewVisibility) { $ui.PanelRev.Visibility = $savedReviewVisibility }
            if ($ui.PanelPlay -and $null -ne $savedPanelPlayVisibility) { $ui.PanelPlay.Visibility = $savedPanelPlayVisibility }
            if ($ui.TxtNoVid -and $null -ne $savedNoVidVisibility) { $ui.TxtNoVid.Visibility = $savedNoVidVisibility }
            if ($ui.BadgePreviewMode -and $null -ne $savedPreviewBadge) { $ui.BadgePreviewMode.Visibility = $savedPreviewBadge }
            if ($ui.BtnReedit) { $ui.BtnReedit.IsEnabled = ($savedLastOut -and (Test-Path -LiteralPath $savedLastOut)) }

            if ($savedSource) {
                $sourceAvailable = $true
                if ($savedSource.IsFile) { $sourceAvailable = Test-Path -LiteralPath $savedSource.LocalPath }
                if (-not $sourceAvailable) {
                    try { $ui.Player.Stop(); $ui.Player.Close(); $ui.Player.Source = $null } catch { }
                    if ($ui.PanelPlay) { $ui.PanelPlay.Visibility = 'Collapsed' }
                    if ($ui.TxtNoVid) { $ui.TxtNoVid.Visibility = 'Visible' }
                    if ($ui.BtnPlay) { $ui.BtnPlay.Content = '▶ Phát' }
                    if ($ui.BtnReedit) { $ui.BtnReedit.IsEnabled = $false }
                    $recoveryPaths = @($delResult.RecoveryPaths | Where-Object { $_ })
                    $missingSourceMessage = if ($recoveryPaths.Count) { "Không thể mở nguồn xem trước đã bị chuyển đi. File cần khôi phục: $($recoveryPaths -join ', ')" } else { "Không thể mở nguồn xem trước đã bị chuyển đi: $($savedSource.LocalPath)" }
                    Show-Toast $missingSourceMessage
                    Add-Log "Không khôi phục được nguồn xem trước $($savedSource.LocalPath); cleanup=$($delResult.CleanupStatus); recovery=$($recoveryPaths -join ', ')" '#EF4444'
                    try { Update-Gallery } catch { }
                    return
                }
                if (-not $script:deleteRestoreGenerationState) { $script:deleteRestoreGenerationState = [pscustomobject]@{ Token = '' } }
                $generationState = $script:deleteRestoreGenerationState
                $restoreState = @{
                    SourceText = $savedSource.ToString()
                    Source = $savedSource
                    Position = $savedPosition
                    WasPlaying = [bool]$savedWasPlaying
                    Completed = $false
                    Opened = $false
                    Failed = $false
                    OpenHandler = $null
                    FailedHandler = $null
                    TimerHandler = $null
                    Timer = [System.Windows.Threading.DispatcherTimer]::new()
                    Expires = [DateTime]::UtcNow.AddSeconds(15)
                    Token = [Guid]::NewGuid().ToString('N')
                }
                $generationState.Token = $restoreState.Token
                $restoreAddLog = ${function:Add-Log}
                $openedAction = {
                    param($sender, $eventArgs)
                    $currentSource = if ($ui.Player.Source) { $ui.Player.Source.ToString() } else { '' }
                    if ($generationState.Token -ne $restoreState.Token -or $currentSource -ne $restoreState.SourceText) {
                        return
                    }
                    $restoreState.Opened = $true
                }.GetNewClosure()
                $failedAction = {
                    param($sender, $eventArgs)
                    $currentSource = if ($ui.Player.Source) { $ui.Player.Source.ToString() } else { '' }
                    if ($generationState.Token -eq $restoreState.Token -and $currentSource -eq $restoreState.SourceText) { $restoreState.Failed = $true }
                }.GetNewClosure()
                $restoreAction = {
                    param($sender, $eventArgs)
                    if ($restoreState.Completed) { return }
                    $currentSource = if ($ui.Player.Source) { $ui.Player.Source.ToString() } else { '' }
                    if ($generationState.Token -ne $restoreState.Token -or $currentSource -ne $restoreState.SourceText) {
                        $restoreState.Completed = $true
                        $restoreState.Timer.Stop()
                        try { $restoreState.Timer.Remove_Tick($restoreState.TimerHandler) } catch { }
                        try { $ui.Player.Remove_MediaOpened($restoreState.OpenHandler) } catch { }
                        try { $ui.Player.Remove_MediaFailed($restoreState.FailedHandler) } catch { }
                        return
                    }
                    if ($restoreState.Failed) {
                        $restoreState.Completed = $true
                        $restoreState.Timer.Stop()
                        try { $restoreState.Timer.Remove_Tick($restoreState.TimerHandler) } catch { }
                        try { $ui.Player.Remove_MediaOpened($restoreState.OpenHandler) } catch { }
                        try { $ui.Player.Remove_MediaFailed($restoreState.FailedHandler) } catch { }
                        & $restoreAddLog "Không mở được media source cần khôi phục: $($restoreState.SourceText)" '#F87171'
                        return
                    }
                    if (-not $restoreState.Opened) {
                        if ([DateTime]::UtcNow -ge $restoreState.Expires) {
                            $restoreState.Completed = $true
                            $restoreState.Timer.Stop()
                            try { $restoreState.Timer.Remove_Tick($restoreState.TimerHandler) } catch { }
                            try { $ui.Player.Remove_MediaOpened($restoreState.OpenHandler) } catch { }
                            try { $ui.Player.Remove_MediaFailed($restoreState.FailedHandler) } catch { }
                            & $restoreAddLog "Hết thời gian chờ MediaOpened để khôi phục nguồn: $($restoreState.SourceText)" '#F87171'
                        }
                        return
                    }
                    $restoreState.Completed = $true
                    $restoreState.Timer.Stop()
                    try { $restoreState.Timer.Remove_Tick($restoreState.TimerHandler) } catch { }
                    try { $ui.Player.Remove_MediaOpened($restoreState.OpenHandler) } catch { }
                    try { $ui.Player.Remove_MediaFailed($restoreState.FailedHandler) } catch { }
                    try { $ui.Player.Position = $restoreState.Position } catch { }
                    if ($restoreState.WasPlaying) {
                        try { $ui.Player.Play() } catch { }
                        if ($ui.BtnPlay) { $ui.BtnPlay.Content = '⏸ Tạm dừng' }
                    } else {
                        try { $ui.Player.Pause() } catch { }
                        if ($ui.BtnPlay) { $ui.BtnPlay.Content = '▶ Phát' }
                    }
                }.GetNewClosure()
                $restoreState.OpenHandler = [System.Windows.RoutedEventHandler]$openedAction
                $restoreState.FailedHandler = [System.EventHandler[System.Windows.ExceptionRoutedEventArgs]]$failedAction
                $restoreState.TimerHandler = [System.EventHandler]$restoreAction
                try {
                    $restoreState.Timer.Interval = [TimeSpan]::FromMilliseconds(50)
                    $restoreState.Timer.Add_Tick($restoreState.TimerHandler)
                    $ui.Player.Add_MediaOpened($restoreState.OpenHandler)
                    $ui.Player.Add_MediaFailed($restoreState.FailedHandler)
                    $ui.Player.Source = $restoreState.Source
                    # Manual LoadedBehavior does not guarantee an open starts
                    # on Source assignment alone; Play initiates MediaOpened.
                    $ui.Player.Play()
                    if ($ui.BtnPlay) { $ui.BtnPlay.Content = '⏸ Tạm dừng' }
                    $restoreState.Timer.Start()
                } catch {
                    $restoreState.Completed = $true
                    try { $restoreState.Timer.Stop(); $restoreState.Timer.Remove_Tick($restoreState.TimerHandler) } catch { }
                    try { $ui.Player.Remove_MediaOpened($restoreState.OpenHandler) } catch { }
                    try { $ui.Player.Remove_MediaFailed($restoreState.FailedHandler) } catch { }
                    Add-Log "Lỗi khôi phục nguồn xem trước: $($_.Exception.Message)" '#F87171'
                }
            } elseif ($ui.BtnPlay) {
                $ui.BtnPlay.Content = if ($savedWasPlaying) { '⏸ Tạm dừng' } else { '▶ Phát' }
            }
            $cleanupStatus = if ($delResult.CleanupStatus) { $delResult.CleanupStatus } else { 'Unknown' }
            $recoveryPaths = @($delResult.RecoveryPaths | Where-Object { $_ })
            $toastText = 'Không thể xóa đủ file. Các file đã được giữ nguyên hoặc khôi phục.'
            if ($recoveryPaths.Count) { $toastText = "Không thể xóa đủ file. Có file cần khôi phục: $($recoveryPaths -join ', ')" }
            Show-Toast $toastText
            Add-Log "Lỗi khi xóa file; cleanup=$cleanupStatus; recovery=$($recoveryPaths -join ', '); chi tiết=$($delResult.Errors -join ' | ')" '#EF4444'
            try { Update-Gallery } catch { }
            return
        }
        Clear-Player
        $successCleanupStatus = if ($delResult.CleanupStatus) { $delResult.CleanupStatus } else { 'Unknown' }
        $successRecoveryPaths = @($delResult.RecoveryPaths | Where-Object { $_ })
        if ($successCleanupStatus -eq 'Complete' -and -not $successRecoveryPaths.Count) {
            Show-Toast "ĐÃ XÓA VIDEO HOÀN TẤT"
            Add-Log "Đã xóa video: $delPath" '#F87171'
        } else {
            Show-Toast "Đã xóa video; còn bản sao tạm cần dọn: $($successRecoveryPaths -join ', ')"
            Add-Log "Đã xóa video: $delPath; cleanup=$successCleanupStatus; recovery=$($successRecoveryPaths -join ', '); chi tiết=$($delResult.Errors -join ' | ')" '#FBBF24'
        }
        try { Update-Gallery } catch {
            Add-Log "Lỗi khi làm mới Kho Video: $($_.Exception.Message)" '#F59E0B'
        }
        if ($isReviewActive) {
            $script:bo++
            Next-Link
        }
    }
})

$ui.BtnSkip.Add_Click({
    if ($script:ps) { Show-Toast 'Hãy đợi tác vụ đang chạy hoàn tất.'; return }
    if (-not $script:queue -or $script:queue.Count -eq 0 -or $script:idx -lt 0 -or $script:idx -ge $script:queue.Count) { Show-Toast 'Không có video đang nghiệm thu trong hàng đợi.'; return }
    $ui.PanelRev.Visibility = 'Collapsed'
    Clear-Player
    $script:bo++
    Add-Log 'Bỏ qua video này.' '#94A3B8'
    Next-Link
})

$ui.BtnStart.Add_Click({
    if ($script:ps) { Show-Toast 'Đang chạy tác vụ — hãy đợi hoàn tất.'; return }
    if ($script:queue -and $script:queue.Count -gt 0) { Show-Toast 'Hãy hoàn tất hoặc bỏ qua hàng đợi đang nghiệm thu trước khi bắt đầu.'; return }
    $links = @()
    if (Get-Command Get-FacebookInputLinks -CommandType Function -ErrorAction SilentlyContinue) {
        $links = @(Get-FacebookInputLinks -Text $ui.TxtLinks.Text)
    } else {
        foreach ($l in ($ui.TxtLinks.Text -split "`r?
")) {
            $t = $l.Trim().Trim('"').Trim("'").Trim()
            if ($t -match '\S') { $links += $t }
        }
    }
    if ($links.Count -eq 0) {
        [System.Windows.MessageBox]::Show('Chưa tìm thấy URL Facebook hợp lệ. Dán link video, Reel hoặc share/r vào ô phía trên.',
            'Thiếu link','OK','Information') | Out-Null
        return
    }
    $xau = @($links | Where-Object { $_ -notmatch 'facebook\.com|fb\.watch' })
    if ($xau.Count -gt 0) {
        $r = [System.Windows.MessageBox]::Show("Có $($xau.Count) dòng không có định dạng link Facebook. Vẫn tiếp tục?",
            'Kiểm tra lại link','YesNo','Warning')
        if ($r -ne 'Yes') { return }
    }
    $duplicateReport = $null
    if (Get-Command Get-FacebookLinkDuplicateReport -ErrorAction SilentlyContinue) {
        try { $duplicateReport = Get-FacebookLinkDuplicateReport -Text $ui.TxtLinks.Text -OutDir $ui.TxtOut.Text }
        catch { Show-Toast 'Không kiểm tra được ID đã tải. Kiểm tra lại thư mục xuất.'; return }
        $links = @($duplicateReport.Links)
        if ($duplicateReport.DownloadedIds.Count -gt 0) {
            Update-LinkDuplicateWarning
            $choice = Confirm-DownloadedReels -Ids $duplicateReport.DownloadedIds
            if ($choice -eq 'Cancel') { return }
            if ($choice -eq 'No') {
                $links = @($links | Where-Object { (Get-FacebookVideoId -Url $_) -notin $duplicateReport.DownloadedIds })
            } elseif ($choice -ne 'Yes') { return }
            if ($links.Count -eq 0) { Show-Toast 'Tất cả video trong danh sách đã tải — không có video mới.'; return }
        }
    }
    if (-not (Test-Path $ui.TxtOut.Text)) { New-Item -ItemType Directory -Path $ui.TxtOut.Text -Force | Out-Null }
    Clear-LogBatch
    if ($ui.TxtLog) { $ui.TxtLog.Clear() }; $script:runLog = ''
    if ($duplicateReport -and $duplicateReport.DuplicateIds.Count -gt 0) {
        Add-Log ('ID lặp, chỉ xử lý một lần: ' + ($duplicateReport.DuplicateIds -join ', ')) '#FBBF24'
    }
    $script:queue = $links; $script:idx = 0; $script:giu = 0; $script:bo = 0
    Start-Link
})

# ------------------------------------------------------------- cap nhat qua GitHub ----
$script:updProc = $null; $script:updMode = ''; $script:updSilent = $false
if ($ui.BtnUpdate) { $ui.BtnUpdate.ToolTip = "Phiên bản hiện tại: v$($script:verLocal) — bấm để kiểm tra bản mới" }
$tUpd = New-Object Windows.Threading.DispatcherTimer
$tUpd.Interval = [TimeSpan]::FromMilliseconds(400)

function Start-UpdateJob([string]$Mode, [bool]$Silent = $false) {
    if ($script:updProc) { return }
    $upd = Join-Path $scriptDir 'updater.ps1'
    if (-not (Test-Path $upd)) { if (-not $Silent) { Show-Toast 'Thiếu file updater.ps1' }; return }
    $script:updMode = $Mode; $script:updSilent = $Silent
    if ($ui.BtnUpdate) { $ui.BtnUpdate.IsEnabled = $false; $ui.BtnUpdate.Content = if ($Mode -eq 'check') { '⏳ Đang kiểm tra...' } else { '⏳ Đang tải...' } }
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = 'powershell.exe'
    $psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$upd`" -Mode $Mode"
    $psi.CreateNoWindow = $true; $psi.UseShellExecute = $false
    $script:updProc = [System.Diagnostics.Process]::Start($psi)
    $tUpd.Start()
}

$tUpd.Add_Tick({
    if (-not $script:updProc -or -not $script:updProc.HasExited) { return }
    $tUpd.Stop(); $script:updProc = $null
    if ($ui.BtnUpdate) { $ui.BtnUpdate.IsEnabled = $true; $ui.BtnUpdate.Content = '🔄 Cập nhật' }
    $st = $null
    try { $st = Get-Content (Join-Path $scriptDir '_update\status.json') -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
    if (-not $st -or -not $st.ok) {
        $err = if ($st) { $st.error } else { 'Không đọc được kết quả' }
        if (-not $script:updSilent) {
            [System.Windows.MessageBox]::Show("Không kiểm tra/tải được bản cập nhật:

$err", 'Kid FB.Y - Cập nhật', 'OK', 'Warning') | Out-Null
        }
        return
    }
    if ($script:updMode -eq 'check') {
        if (-not $st.hasUpdate) {
            if (-not $script:updSilent) { Show-Toast "ĐANG DÙNG BẢN MỚI NHẤT (v$($script:verLocal))" }
            return
        }
        if ($ui.BtnUpdate) { $ui.BtnUpdate.Content = "🔔 Có bản v$($st.remote)" }
        if ($script:updSilent -and -not $st.mandatory) { Add-Log "Có bản cập nhật mới v$($st.remote) — bấm nút Cập nhật để cài." '#34D399'; return }
        if ($script:ps) { Show-Toast 'Đang chạy tác vụ — cập nhật sau khi xong'; return }
        $log = (@($st.changelog) | ForEach-Object { "  • $_" }) -join "
"
        $kb = [math]::Round(([double]$st.size) / 1KB, 0)
        $r = [System.Windows.MessageBox]::Show("Có bản mới v$($st.remote) (hiện tại v$($st.local)).

Thay đổi:
$log

Dung lượng: ~$kb KB. Cập nhật ngay?",
            'Kid FB.Y - Cập nhật', 'YesNo', 'Question')
        if ($r -eq 'Yes') { Start-UpdateJob 'download' $false }
        return
    }
    if ($script:updMode -eq 'download' -and $st.ready) {
        [System.Windows.MessageBox]::Show("Đã tải xong bản v$($st.remote).
Tool sẽ khởi động lại để áp dụng.", 'Kid FB.Y - Cập nhật', 'OK', 'Information') | Out-Null
        $exe = Join-Path $root 'Kid-FB.Y.exe'
        if (Test-Path $exe) {
            Start-Process -FilePath $exe -WorkingDirectory $root
            $win.Close()
        } else {
            [System.Windows.MessageBox]::Show('Không tìm thấy Kid-FB.Y.exe. Hãy mở lại tool bằng Kid-FB.Y.exe để áp dụng bản mới.', 'Kid FB.Y', 'OK', 'Warning') | Out-Null
        }
    }
})

if ($ui.BtnUpdate) {
    $ui.BtnUpdate.Add_Click({
        if ($script:ps) { Show-Toast 'Đang chạy tác vụ — hãy Dừng hoặc đợi xong rồi cập nhật'; return }
        Start-UpdateJob 'check' $false
    })
}

$win.Add_Closing({ param($sender,$eventArgs)
    $gifPending=($script:gifSelectionWorker -or ($script:gifCancelledWorkers -and $script:gifCancelledWorkers.Count -gt 0))
    if($gifPending){
        $script:closeAfterGifStop = $true
        $script:gifSelectionGeneration++
        try { Stop-GifSelectionWorker } catch { }
    }
    if ($script:ps) {
        $eventArgs.Cancel = $true
        $script:closeAfterStop = $true
        Stop-Engine
        return
    }
    if ($gifPending -or ($script:gifCancelledWorkers -and $script:gifCancelledWorkers.Count -gt 0)) { $eventArgs.Cancel=$true; return }
    try { if ($tUpd) { $tUpd.Stop() } } catch { }
    try { if ($script:updProc -and -not $script:updProc.HasExited) { $script:updProc.Kill() } } catch { }
    $script:gifSelectionGeneration++
    try { Stop-GifSelectionWorker } catch { }
    if ($script:gifPlayer) { try { $script:gifPlayer.Close() } catch { }; $script:gifPlayer=$null }
    if ($ui.MediaVideoGif) { try { $ui.MediaVideoGif.Stop() } catch { }; try { $ui.MediaVideoGif.Close() } catch { }; $ui.MediaVideoGif.Source=$null }
    try { Stop-Engine } catch { }
    try { if ($tLinkWarning) { $tLinkWarning.Stop() } } catch { }
    try { if ($tPlay) { $tPlay.Stop() } } catch { }
    try { if ($timer) { $timer.Stop() } } catch { }
    try { if ($script:tToast) { $script:tToast.Stop() } } catch { }
    try { Flush-LogBatch } catch { }
    try { if ($script:logFlushTimer) { $script:logFlushTimer.Stop() } } catch { }
})

try {
    # ------------------------------------------------------------------ chay ----
    if (-not (Test-Path $engine)) {
        if ($SelfTest) { throw "Khong tim thay engine: $engine" }
        [System.Windows.MessageBox]::Show("Không tìm thấy kid-fby.ps1 cạnh file này.

$engine",
            'Thiếu file','OK','Error') | Out-Null
        return
    }
    # Auto scan gallery va tools on launch
    Update-Gallery
    Update-ToolsStatus

    if ($SelfTest) {
        foreach ($k in $ui.Keys) {
            if ($null -eq $ui[$k]) { throw "Thieu thanh phan giao dien: $k" }
        }
        if ($ui.TxtOut.Text -ne (Join-Path $root 'output')) { throw 'Thu muc xuat khoi tao khong dung.' }
        if ($ui.TxtAppVersion.Text -ne "v$($script:verLocal)") { throw 'Nhan phien ban khoi tao khong dung.' }
        $ud = Join-Path $scriptDir '_update'
        if (-not (Test-Path -LiteralPath $ud)) { New-Item -ItemType Directory -Path $ud -Force | Out-Null }
        [System.IO.File]::WriteAllText((Join-Path $ud 'BOOT_OK'), (Get-Date).ToString('o'))
        Write-Host "SelfTest: Kid FB.Y khoi tao thanh cong, $($ui.Keys.Count) thanh phan giao dien"
        return
    }

    # Auto preview latest finished video if available
    $latestVid = Get-ChildItem -Path $ui.TxtOut.Text -Filter '*-3-hoan-chinh.mp4' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if ($latestVid -and (Test-Path $latestVid.FullName)) {
        Load-Player $latestVid.FullName
        $ui.TxtRev.Text = "Đang xem lại tác phẩm hoàn tất gần nhất: $($latestVid.Name)"
        $ui.BtnKeep.Visibility = 'Collapsed'
        $ui.BtnRedo.Content = '🔄 Ghi âm lại'
        $ui.PanelRev.Visibility = 'Visible'
    } else {
        Clear-Player
    }

    $icoFile = Join-Path $root 'Kid-FB.Y.ico'
    if (-not (Test-Path $icoFile)) { $icoFile = Join-Path $scriptDir 'Kid-FB.Y.ico' }
    if (Test-Path $icoFile) {
        try {
            $win.Icon = [System.Windows.Media.Imaging.BitmapFrame]::Create((New-Object System.Uri([System.IO.Path]::GetFullPath($icoFile))))
        } catch { }
    }

    $win.Add_ContentRendered({
        # Bao cho launcher biet ban hien tai khoi dong OK (de khong rollback)
        try {
            $ud = Join-Path $scriptDir '_update'
            if (-not (Test-Path $ud)) { New-Item -ItemType Directory -Path $ud -Force | Out-Null }
            [System.IO.File]::WriteAllText((Join-Path $ud 'BOOT_OK'), (Get-Date).ToString('o'))
        } catch { }
        try {
            if ($ui.BtnCheck) {
                $ui.BtnCheck.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
            }
        } catch { }
        try { Start-UpdateJob 'check' $true } catch { }
    })
    [void]$win.ShowDialog()
} catch {
    if ($SelfTest) { Write-Error $_ -ErrorAction Continue; exit 1 }
    [System.Windows.MessageBox]::Show("Đã xảy ra sự cố giao diện:

$($_.Exception.Message)", "Kid FB.Y", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
}
